import{_ as s,o as a,c as n,a2 as o}from"./chunks/framework.CmvPqeTF.js";const m=JSON.parse('{"title":"终端 I/O 数据流","description":"","frontmatter":{},"headers":[],"relativePath":"dev/terminal-io.md","filePath":"dev/terminal-io.md","lastUpdated":1788361893000}'),t={name:"dev/terminal-io.md"};function i(l,e,d,r,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="终端-i-o-数据流" tabindex="-1">终端 I/O 数据流 <a class="header-anchor" href="#终端-i-o-数据流" aria-label="Permalink to &quot;终端 I/O 数据流&quot;">​</a></h1><p>终端是 vShell 中数据量最大、实时性最强的通道，其 I/O 全部走 <strong>Wails Events</strong>，并有专门的缓冲合并机制。</p><hr><h2 id="_1-链路全景" tabindex="-1">1. 链路全景 <a class="header-anchor" href="#_1-链路全景" aria-label="Permalink to &quot;1. 链路全景&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入（按键）                                    输出（回显 / 命令输出）</span></span>
<span class="line"><span>─────────────────────────────────────────────────────────────────────</span></span>
<span class="line"><span>xterm onData                                    Go goroutine</span></span>
<span class="line"><span>   │                                              │ io.Copy</span></span>
<span class="line"><span>   ▼                                              ▼</span></span>
<span class="line"><span>Events.Emit(&quot;terminal:stdin&quot;)              stdoutPipe ──► flushingWriter（50ms 缓冲）</span></span>
<span class="line"><span>   {sessionID, data}                             │ 每 50ms 合并 flush</span></span>
<span class="line"><span>   │                                              ▼</span></span>
<span class="line"><span>app.go 监听                                onEvent(&quot;terminal:stdout&quot;, {sessionID, data})</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   ▼                                              ▼</span></span>
<span class="line"><span>session.WriteStdin(data)                   useTerminalManager 按 sessionID 分发</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   ▼                                              ▼</span></span>
<span class="line"><span>stdinPipe ──► 远端 PTY ──► Shell            term.write(data) 渲染</span></span></code></pre></div><p>调整大小：xterm <code>onResize</code> → <code>terminal:resize {sessionID, rows, cols}</code> → <code>session.WindowChange(rows, cols)</code>。</p><h2 id="_2-会话建立-ssh-session-go" tabindex="-1">2. 会话建立（<code>ssh/session.go</code>） <a class="header-anchor" href="#_2-会话建立-ssh-session-go" aria-label="Permalink to &quot;2. 会话建立（\`ssh/session.go\`）&quot;">​</a></h2><p>每开一个终端标签：</p><ol><li>在复用的 <code>ssh.Client</code> 上 <code>NewSession()</code></li><li><code>RequestPty(&quot;xterm-256color&quot;, 24, 80, modes)</code> —— <code>ECHO: 1</code>，TTY 收发速率 14400</li><li><strong>先建管道再启 shell</strong>：<code>StdinPipe</code> / <code>StdoutPipe</code> / <code>StderrPipe</code>（避免 Shell 启动后管道未就绪丢数据）</li><li><code>sess.Shell()</code></li><li>stdout / stderr 各接一个 <code>flushingWriter</code>，各起 goroutine <code>io.Copy</code></li><li>第三个 goroutine <code>sess.Wait()</code> 结束后发 <code>terminal:closed {sessionID}</code>，前端据此显示断连提示</li></ol><h2 id="_3-flushingwriter-50ms-批量合并" tabindex="-1">3. flushingWriter：50ms 批量合并 <a class="header-anchor" href="#_3-flushingwriter-50ms-批量合并" aria-label="Permalink to &quot;3. flushingWriter：50ms 批量合并&quot;">​</a></h2><p>PTY 输出常以字节级碎包到达（vim / top 等全屏程序尤其明显），逐字节 Emit 事件会造成大量跨语言序列化开销。<code>flushingWriter</code> 的做法：</p><table tabindex="0"><thead><tr><th>机制</th><th>实现</th></tr></thead><tbody><tr><td><code>Write(p)</code></td><td>只把 p 追加进 <code>pending</code> 缓冲，立即返回（不阻塞读取方）</td></tr><tr><td><code>flushTicker</code></td><td>每 <strong>50ms</strong> 把整个 <code>pending</code> 作为一次事件载荷 Emit，复用底层数组（<code>pending[:0]</code>）</td></tr><tr><td>结束</td><td><code>io.Copy</code> 返回后强制 <code>Flush()</code> 一次，保证尾包不丢</td></tr></tbody></table><p>即：<strong>按时间窗口合并，不设缓冲上限</strong>。对终端场景，50ms 低于人眼感知阈值，既流畅又把事件量压缩了几个数量级。</p><h2 id="_4-前端分发-useterminalmanager-ts" tabindex="-1">4. 前端分发（<code>useTerminalManager.ts</code>） <a class="header-anchor" href="#_4-前端分发-useterminalmanager-ts" aria-label="Permalink to &quot;4. 前端分发（\`useTerminalManager.ts\`）&quot;">​</a></h2><ul><li>全局单例监听 <code>terminal:stdout</code>，按 <code>sessionID</code> 写入对应 <code>terminals</code> Map 中的 xterm 实例 —— 多标签并存时各终端只收到自己的数据</li><li><code>terminal:closed</code> 把对应标签标记为断开，并写入黄色提示「--- 连接已断开，按回车键重连 ---」</li><li>按回车触发重连：断开旧会话 → 重新 <code>ConnectSSH</code> → 原标签接续新 sessionID</li></ul><h2 id="_5-渲染" tabindex="-1">5. 渲染 <a class="header-anchor" href="#_5-渲染" aria-label="Permalink to &quot;5. 渲染&quot;">​</a></h2><ul><li><code>XTerminal.vue</code>：xterm.js v6 + FitAddon（自动适配容器尺寸）+ WebglAddon（失败回退 canvas）</li><li>字体 / 字号 / 配色来自 settings store，watch 实时热更新 <code>term.options</code></li><li><code>attachCustomKeyEventHandler</code> 拦截复制 / 粘贴组合键（命中返回 false 不进 PTY）；macOS 上 <code>Ctrl+C</code> / <code>Ctrl+V</code> 永不拦截，保留远端语义</li></ul><h2 id="_6-设计要点小结" tabindex="-1">6. 设计要点小结 <a class="header-anchor" href="#_6-设计要点小结" aria-label="Permalink to &quot;6. 设计要点小结&quot;">​</a></h2><ol><li>输入输出都是事件流，<strong>没有任何同步 Call 参与 I/O</strong>（红线 1）</li><li>PTY 必须 <code>xterm-256color</code> + <code>Shell()</code>（红线 4），不使用 exec 模拟</li><li>输出方向做时间窗口合并（50ms），输入方向天然低频无需合并</li><li>stderr 独立管道与事件（<code>terminal:stderr</code>），当前前端未消费</li></ol><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/terminal.html">终端使用</a></li><li><a href="./architecture.html">架构总览</a></li></ul>`,22)])])}const u=s(t,[["render",i]]);export{m as __pageData,u as default};
